const toast = message => { const el = document.querySelector('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(()=>el.classList.remove('show'),2200); };
function distanceKm(aLat,aLon,bLat,bLon) { const toRad=value=>value*Math.PI/180; const dLat=toRad(bLat-aLat); const dLon=toRad(bLon-aLon); const a=Math.sin(dLat/2)**2+Math.cos(toRad(aLat))*Math.cos(toRad(bLat))*Math.sin(dLon/2)**2; return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)); }
function nearestKnownCity(latitude,longitude) { return Object.entries(cityCenters).map(([city,[lat,lon]])=>({city,distance:distanceKm(latitude,longitude,lat,lon)})).sort((a,b)=>a.distance-b.distance)[0]; }
function userLocationLabel() { if (locationState.status==='ready') return `Espacios cerca de ${locationState.city}`; if (locationState.status==='loading') return 'Detectando tu ubicación…'; return 'Activa tu ubicación para ver espacios cercanos'; }
async function reverseGeocode(latitude,longitude) { const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}&zoom=10&addressdetails=1&accept-language=es`; const response=await fetch(url,{headers:{Accept:'application/json'}}); if(!response.ok) throw new Error('No se pudo identificar la ciudad'); const data=await response.json(); const address=data.address||{}; return {city:address.city||address.town||address.village||address.municipality||address.county,country:address.country||''}; }
function applyDetectedLocation(latitude,longitude,city,country) { const label=city&&country?`${city}, ${country}`:nearestKnownCity(latitude,longitude)?.city||'Bogotá, Colombia'; locationState.status='ready'; locationState.latitude=latitude; locationState.longitude=longitude; locationState.city=city||label.split(',')[0]; locationState.country=country||label.split(',')[1]?.trim()||'Colombia'; searchState.location=label; if(!cityCenters[label]) cityCenters[label]=[latitude,longitude]; toast(`Ubicación detectada: ${label}`); render(); }
async function requestUserLocation(force=false) { if(locationState.requested&&!force) return; locationState.requested=true; if(!navigator.geolocation){ locationState.status='unavailable'; return; } locationState.status='loading'; if(active==='discover') render(); navigator.geolocation.getCurrentPosition(async position=>{ const {latitude,longitude}=position.coords; try { const place=await reverseGeocode(latitude,longitude); applyDetectedLocation(latitude,longitude,place.city,place.country); } catch(error) { const fallback=nearestKnownCity(latitude,longitude); applyDetectedLocation(latitude,longitude,fallback?.city?.split(',')[0],fallback?.city?.split(',')[1]?.trim()); } },()=>{ locationState.status='denied'; if(active==='discover') render(); toast('Puedes activar la ubicación desde el navegador para recibir sugerencias cercanas'); },{enableHighAccuracy:true,timeout:10000,maximumAge:300000}); }
const navItems = [['discover','Inicio','home'],['map','Explorar mapa','map'],['potential','Espacios con potencial','add_business'],['favorites','Favoritos','favorite'],['inbox','Mensajes','chat_bubble'],['owner','Soy propietario','storefront'],['verify','Verificar negocio','verified_user']];
function shell(content) { app.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="${logo}" alt="Localmente"/></div><nav class="nav">${navItems.map(([id,label,icon])=>`<button class="${active===id?'active':''}" data-route="${id}"><span class="material-symbols-outlined">${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="profile-chip"><div class="avatar">RM</div><div><strong>Rodrigo M.</strong><small>Cuenta personal</small></div></div></div></aside><main class="main"><div class="topbar"><div><p class="eyebrow">Localmente</p><h2>${active==='owner'?'Panel del propietario':active==='verify'?'Verificación del negocio':active==='potential'?'Espacios con potencial de local':active==='publish'?'Crear registro de espacio':'Encuentra tu próximo lugar'}</h2></div><div class="top-actions"><button class="icon-btn" title="Notificaciones" onclick="toast('No tienes alertas nuevas')"><span class="material-symbols-outlined">notifications</span></button><button class="icon-btn" title="Perfil" onclick="active='profile';render()"><span class="material-symbols-outlined">account_circle</span></button><button class="primary-btn" onclick="openReserve()">Publicar espacio</button></div></div>${content}</main></div><div id="modal-root"></div>`; document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{active=b.dataset.route; render()}); }
function card(item) { const amount=typeof item.price==='number'?`$${new Intl.NumberFormat('es-CO').format(item.price)}`:item.price; return `<article class="card"><div class="card-image" style="background-image:url('${item.image}')"><span class="badge ${item.orange?'orange':''}">${item.badge||'Disponible'}</span><button class="heart" onclick="toggleHeart(this)"><span class="material-symbols-outlined">favorite</span></button></div><div class="card-content"><h3>${item.title||item.name}</h3><div class="card-location"><span class="material-symbols-outlined">location_on</span>${item.location}</div><div class="card-meta"><div class="tags">${(item.tags||[]).map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="price">${amount}<small>${item.unit}</small></div></div></div></article>`; }
function recommendedSpaces() { const city=normalizeCity(searchState.location); const candidates=ensureCitySpaces(city); if(!locationState.latitude||!locationState.longitude) return candidates.slice(0,6); return candidates.map(space=>({...space,nearbyDistance:distanceKm(locationState.latitude,locationState.longitude,space.latitude,space.longitude)})).sort((a,b)=>a.nearbyDistance-b.nearbyDistance).slice(0,6); }
function discover() { const resultLabel=searchState.furnishing==='unfurnished'?'Espacios vacíos y sin amoblar':searchState.furnishing==='furnished'?'Espacios amoblados':locationState.status==='ready'?'Espacios recomendados cerca de ti':'Populares cerca de ti'; return `<section class="view"><div class="hero"><div><p class="eyebrow" style="color:#bfffe7">Tu espacio, tu momento</p><h1>Haz que tu próxima idea encuentre su lugar.</h1><p>Descubre locales listos para crear, vender, reunirte y hacer crecer lo que imaginas.</p><button class="primary-btn" onclick="document.querySelector('#search').focus()">Explorar espacios <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div><img class="hero-mark" src="${logo}" alt=""/></div><div class="search-bar" id="search"><div class="search-field"><span>UBICACIÓN</span><strong>${searchState.location}</strong></div><div class="search-field"><span>TIPO DE ESPACIO</span><strong>Cualquier categoría</strong></div><div class="search-field"><span>PRESUPUESTO</span><strong>Cualquier presupuesto</strong></div><div class="search-field"><span>FECHAS</span><strong>Agregar fechas</strong></div><button class="search-go" onclick="active='filters';render()"><span class="material-symbols-outlined">tune</span></button></div><div class="section-head"><h2>Explora por categoría</h2><button class="link-btn" onclick="toast('Todas las categorías disponibles')">Ver todas</button></div><div class="category-row">${[['restaurant','Gastro'],['shopping_bag','Retail'],['work','Oficinas'],['medical_services','Salud'],['face','Belleza'],['build','Talleres']].map((x,i)=>`<button class="category ${i===0?'active':''}" onclick="this.classList.toggle('active')"><span class="material-symbols-outlined">${x[0]}</span>${x[1]}</button>`).join('')}</div><div class="potential-callout"><div><p class="eyebrow">Una nueva forma de empezar</p><h2>¿Tienes un espacio en casa?</h2><p>Descubre garajes, habitaciones con ventana a la calle y jardines frontales que pueden convertirse en tu próximo local en Bogotá.</p></div><button class="secondary-btn" onclick="active='potential';render()">Ver espacios con potencial <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div><div class="section-head"><div><h2>${resultLabel}</h2>${searchState.furnishing==='unfurnished'?'<p class="results-note">Mostrando únicamente espacios libres, listos para adaptar a tu negocio.</p>':''}</div><button class="link-btn" onclick="active='map';render()">Ver todos</button></div><div class="cards">${recommendedSpaces().map(card).join('')}</div></section>`; }
function potential() { return `<section class="view potential-view"><div class="potential-hero"><div><p class="eyebrow">Espacios con potencial de local</p><h1>Convierte un rincón de tu casa en una oportunidad.</h1><p>Explora espacios personales en barrios de Bogotá que pueden recibir una idea comercial por horas, días o semanas.</p></div><span class="material-symbols-outlined potential-hero-icon">home_work</span></div><div class="section-head potential-heading"><div><h2>Oportunidades cerca de ti</h2><p>Inspiradas en las casas y frentes comerciales de Galerías, Teusaquillo y barrios vecinos.</p></div><button class="secondary-btn" onclick="active='discover';render()"><span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_back</span> Volver al inicio</button></div><div class="cards potential-cards">${potentialSpaces.map(item=>`<article class="card potential-card"><div class="card-image" style="background-image:url('${item.image}')"><span class="badge orange">${item.badge}</span><button class="heart" onclick="toggleHeart(this)"><span class="material-symbols-outlined">favorite</span></button></div><div class="card-content"><h3>${item.title}</h3><div class="card-location"><span class="material-symbols-outlined">location_on</span>${item.location}</div><p class="potential-description">${item.description}</p><div class="card-meta"><div class="tags">${item.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="price">${item.price}<small>${item.unit}</small></div></div><button class="potential-action" onclick="toast('Te mostraremos cómo activar este espacio')">Me interesa este espacio</button></div></article>`).join('')}</div></section>`; }
function mapView() { return `<section class="view"><div class="map-panel"><div class="map-top"><span class="material-symbols-outlined">arrow_back</span><input value="Malasaña, Madrid" aria-label="Ubicación"/><button class="icon-btn" onclick="active='filters';render()"><span class="material-symbols-outlined">tune</span></button></div><span class="pin" style="top:33%;left:20%">€45/h</span><span class="pin selected" style="top:50%;left:56%">€180/d</span><span class="pin" style="top:72%;left:31%">€60/h</span><button class="secondary-btn" style="position:absolute;left:24px;bottom:145px" onclick="toast('Cambiando a vista de lista')"><span class="material-symbols-outlined" style="vertical-align:middle">format_list_bulleted</span> Lista</button><button class="icon-btn" style="position:absolute;right:24px;bottom:145px;background:white" onclick="toast('Ubicación actualizada')"><span class="material-symbols-outlined">my_location</span></button><div class="map-list">${listings.slice(0,2).map(x=>`<div class="map-card" onclick="active='booking';render()"><div class="mini-img" style="background-image:url('${x.image}')"></div><div class="card-content"><h3>${x.title}</h3><div class="card-location">${x.tags.join(' · ')} · 45m²</div><div class="price">${x.price}${x.unit}</div></div></div>`).join('')}</div></div></section>`; }
function publish() { return `<section class="view flow-screen publish-view"><button class="back-btn" onclick="active='discover';render()"><span class="material-symbols-outlined">arrow_back</span> Volver al inicio</button><div class="section-head publish-heading"><div><p class="eyebrow">Registro de propietario</p><h1>Publica tu espacio</h1><p>Cuéntanos qué lugar quieres convertir en una oportunidad comercial temporal.</p></div><span class="publish-step">Paso 1 de 3</span></div><div class="publish-layout"><div class="panel publish-panel"><h2>Fotos del espacio</h2><p class="panel-help">Muestra el acceso, la fachada, la luz y el área completa. Puedes subir hasta 6 fotos.</p><label class="photo-upload"><input type="file" accept="image/*" multiple onchange="handlePhotoUpload(this)"><span class="material-symbols-outlined">add_photo_alternate</span><strong>Subir fotos del local</strong><small>JPG o PNG · Arrastra tus imágenes aquí</small></label><div id="photo-preview" class="photo-preview"></div><div class="publish-tip"><span class="material-symbols-outlined">lightbulb</span><span>Una buena foto de la entrada ayuda a que las personas entiendan cómo funciona el espacio.</span></div></div><div class="panel publish-panel"><h2>Datos del local</h2><div class="form-grid"><div class="form-field"><label>NOMBRE DEL ESPACIO</label><input placeholder="Ej. Garaje Galerías"/></div><div class="form-field"><label>TIPO DE ESPACIO</label><select><option>Local comercial</option><option>Garaje</option><option>Habitación con ventana a la calle</option><option>Jardín frontal</option><option>Corredor de edificio</option></select></div><div class="form-field"><label>ÁREA APROXIMADA</label><input type="number" min="1" placeholder="Ej. 18"/></div><div class="form-field"><label>UNIDAD</label><select><option>m²</option><option>m lineales</option></select></div><div class="form-field full-field"><label>DIRECCIÓN O ZONA</label><input placeholder="Ej. Calle 53 con Carrera 24, Galerías, Bogotá"/></div><div class="form-field full-field"><label>ESPECIFICACIONES</label><textarea rows="4" placeholder="Acceso independiente, ventana a la calle, baño, luz natural, altura, restricciones..."></textarea></div></div></div><div class="panel publish-panel publish-questionnaire"><h2>Cuestionario del espacio</h2><p class="panel-help">Estas respuestas ayudan a las personas a saber si el lugar sirve para su idea.</p><div class="question"><strong>¿Qué tipo de actividad puede recibir?</strong><div class="question-options"><label><input type="checkbox"> Gastro</label><label><input type="checkbox"> Retail</label><label><input type="checkbox"> Servicios</label><label><input type="checkbox"> Talleres</label></div></div><div class="question"><strong>¿Cómo es el acceso?</strong><div class="question-options"><label><input type="radio" name="access"> Directo desde la calle</label><label><input type="radio" name="access"> Por zona común</label><label><input type="radio" name="access"> Requiere coordinación</label></div></div><div class="question"><strong>¿Qué disponibilidad ofreces?</strong><div class="question-options"><label><input type="checkbox"> Por hora</label><label><input type="checkbox"> Por día</label><label><input type="checkbox"> Por semana</label></div></div></div></div><div class="publish-actions"><button class="secondary-btn" onclick="active='discover';render()">Guardar y salir</button><button class="primary-btn" onclick="toast('Registro guardado como borrador')">Guardar registro <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div></section>`; }
function owner() { return `<section class="view"><div class="dashboard-grid"><div class="metric-card"><p class="eyebrow" style="color:#d9c4ff">Ingresos de este mes</p><div class="metric">€12.450</div><div class="metric-row"><div>Ocupación media<b>92%</b></div><div>Días alquilados<b>28/31</b></div></div></div><div class="chart-card"><div class="section-head" style="margin:0"><h3>Visitas al perfil</h3><span style="color:var(--muted);font-size:13px">Últimos 7 días</span></div><div class="bars">${[35,60,45,78,40,92,65].map((h,i)=>`<div class="bar ${i===5?'active':''}" style="height:${h}%"></div>`).join('')}</div><div class="bar-labels">${['L','M','X','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}</div></div></div><div class="section-head"><h2>Mis espacios</h2><button class="link-btn">Ver todos</button></div><div class="cards">${listings.slice(1).concat(listings.slice(0,1)).map(card).join('')}</div><div class="section-head"><h2>Próximas reservas</h2><button class="link-btn" onclick="active='inbox';render()">Ver mensajes</button></div><div class="reservations"><div class="reservation"><div class="avatar">CM</div><div class="reservation-info"><strong>Carlos Méndez</strong><p>The Creative Loft · 12 oct - 14 oct</p></div><span class="reservation-date">Mañana</span><span class="material-symbols-outlined">chat_bubble</span></div><div class="reservation"><div class="avatar">ER</div><div class="reservation-info"><strong>Elena Rius</strong><p>Kitchen Lab Industrial · 16 oct - 16 oct</p></div><span class="reservation-date">En 4 días</span><span class="material-symbols-outlined">chat_bubble</span></div></div></section>`; }
