function openReserve() { document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal publish-start"><button class="icon-btn modal-close" onclick="this.closest('.modal-backdrop').remove()"><span class="material-symbols-outlined">close</span></button><p class="eyebrow">Publicar espacio</p><h2>Empieza a ofrecer tu espacio por horas, días o semanas</h2><p class="modal-copy">Registra un local comercial o transforma un espacio personal en una oportunidad para otros negocios.</p><div class="publish-choice"><span class="material-symbols-outlined">add_business</span><div><strong>Crear registro de espacio</strong><small>Sube fotos, datos, medidas y disponibilidad.</small></div><button class="primary-btn" onclick="active='publish';render()">Crear registro</button></div><div class="publish-choice muted-choice"><span class="material-symbols-outlined">draft</span><div><strong>Continuar un borrador</strong><small>Retoma un registro que ya empezaste.</small></div><button class="secondary-btn" onclick="toast('No tienes borradores guardados')">Abrir</button></div></div></div>`; }
function handlePhotoUpload(input) { const preview=document.querySelector('#photo-preview'); if (!preview || !input.files.length) return; preview.innerHTML=Array.from(input.files).slice(0,6).map(file=>`<div class="photo-preview-item"><img src="${URL.createObjectURL(file)}" alt="Vista previa del espacio"><span>${file.name}</span></div>`).join(''); }
function toggleHeart(btn) { btn.classList.toggle('liked'); btn.style.color=btn.classList.contains('liked')?'#fd4e79':'var(--purple)'; toast(btn.classList.contains('liked')?'Añadido a favoritos':'Eliminado de favoritos'); }
const interventionOptions = ['Sí, está permitido','Solo con mi autorización','No está permitido','No aplica'];
const interventionSections = [
  ['1. Paredes y estructura',['Perforar las paredes','Instalar chazos, tornillos o anclajes','Instalar repisas','Instalar soportes para televisores o pantallas','Instalar cuadros, decoración o elementos publicitarios','Pintar las paredes','Cambiar temporalmente los colores del espacio','Instalar papel tapiz o vinilos adhesivos','Instalar paneles decorativos','Construir divisiones livianas','Instalar divisiones removibles','Instalar divisiones en drywall','Retirar divisiones existentes','Derribar muros','Realizar modificaciones estructurales']],
  ['2. Pisos y techos',['Instalar piso temporal','Cambiar el piso existente','Instalar tapetes o alfombras adheridas','Perforar pisos','Perforar techos','Instalar elementos colgantes','Instalar cielo raso','Instalar estructuras decorativas temporales']],
  ['3. Fachada y publicidad',['Instalar avisos comerciales','Instalar avisos luminosos','Instalar pendones','Colocar vinilos en vitrinas','Modificar temporalmente la fachada','Instalar publicidad en el exterior','Ubicar mesas, exhibidores o productos frente al espacio','Usar publicidad sonora']],
  ['4. Instalaciones eléctricas',['Instalar nuevas tomas eléctricas','Mover tomas existentes','Instalar nuevas luminarias','Cambiar luminarias existentes','Instalar equipos de alto consumo','Instalar aire acondicionado','Instalar cámaras de seguridad','Instalar cableado de internet o redes','Usar extensiones eléctricas temporales']],
  ['5. Agua, baños y plomería',['Instalar nuevos puntos de agua','Modificar puntos de agua existentes','Instalar lavamanos','Instalar lavacabezas','Realizar modificaciones en baños','Instalar equipos conectados al desagüe','Modificar tuberías']],
  ['6. Cocina y alimentos',['Preparar alimentos','Cocinar dentro del espacio','Usar cocina eléctrica','Usar cocina a gas','Instalar estufa','Instalar horno','Instalar freidora','Instalar nevera o congelador','Instalar campana extractora','Modificar sistemas de extracción','Vender alimentos','Vender bebidas','Vender bebidas alcohólicas (con permisos legales)']],
  ['7. Mobiliario',['Mover el mobiliario existente','Retirar temporalmente el mobiliario','Ingresar muebles propios','Instalar muebles anclados','Instalar vitrinas','Instalar mostradores','Instalar estanterías']],
  ['8. Actividades y funcionamiento',['Usar música','Usar música amplificada','Realizar eventos','Atender público','Realizar actividades nocturnas','Permitir mascotas','Permitir fumar','Usar maquinaria','Realizar actividades con olores','Realizar actividades con humo','Realizar actividades con ruido','Almacenar mercancía','Realizar entregas y domicilios','Realizar cargue y descargue']],
  ['9. Horarios',['Tener un horario máximo de funcionamiento']],
  ['10. Tipos de negocios permitidos',['Restaurante','Cafetería','Panadería','Comidas rápidas','Salón de belleza','Barbería','Spa / estética','Boutique','Calzado','Tecnología','Oficina','Consultorio','Coworking','Papelería','Minimercado','Floristería','Showroom','Estudio fotográfico','Taller creativo','Pop-up store','Feria / exhibición','Otro tipo de negocio']],
  ['11. Entrega del espacio',['Entregar el espacio limpio','Retirar toda la mercancía','Retirar avisos y publicidad','Retirar instalaciones temporales','Reparar perforaciones realizadas','Restaurar pintura cuando corresponda','Reinstalar el mobiliario en su ubicación original','Retirar residuos','Entregar llaves o dispositivos de acceso','Entregar el espacio en las mismas condiciones']]
];
function interventionPanel() { return `<div class="panel publish-panel modifications-panel"><h2>Intervenciones y condiciones del espacio</h2><p class="panel-help">Cuéntanos qué puede y qué no puede modificar un emprendedor durante su reserva. Esta información aparecerá en la publicación.</p><div class="intervention-legend">${interventionOptions.map((option,i)=>`<span class="legend-${i}">${option}</span>`).join('')}</div>${interventionSections.map(([title,questions])=>`<section class="intervention-section"><h3>${title}</h3>${title.startsWith('9.')?`<div class="intervention-row"><span>¿Existe un horario máximo de funcionamiento?</span>${interventionSelect('Horario máximo')}</div><div class="time-grid"><label>Hora de apertura<input type="time"></label><label>Hora máxima de cierre<input type="time"></label></div><div class="days-row"><strong>Días permitidos</strong>${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(day=>`<label><input type="checkbox"> ${day}</label>`).join('')}</div>`:questions.map(question=>`<div class="intervention-row"><span>${question}</span>${title.startsWith('10.')?`<select aria-label="${question}"><option>Permitido</option><option>Solo con mi autorización</option><option>No permitido</option><option>No aplica</option></select>`:interventionSelect(question)}</div>`).join('')}</section>`).join('')}<div class="special-fields"><label>Tamaño máximo permitido para avisos<input placeholder="Ej. 80 cm x 120 cm"></label><label>Capacidad eléctrica disponible<input placeholder="Ej. 20 amperios / 110V"></label><label>Observaciones sobre la fachada<textarea rows="2" placeholder="Describe condiciones de fachada, vitrinas o acceso exterior..."></textarea></label><label>Actividades que NO aceptas<textarea rows="2" placeholder="Ej. No se permiten bares, humo ni actividades nocturnas..."></textarea></label><label>Condiciones especiales del propietario<textarea rows="3" placeholder="Escribe aquí cualquier regla o condición especial de tu espacio..."></textarea></label></div><div class="intervention-summary"><h3>Resumen antes de publicar</h3><p class="panel-help">Este resumen será visible y deberá ser aceptado por el emprendedor antes de reservar.</p><div class="summary-columns"><div><strong>✓ Este espacio permite</strong><ul data-summary="allowed"><li>Instalación de avisos</li><li>Mover mobiliario</li></ul></div><div><strong>⚠ Requiere autorización del propietario</strong><ul data-summary="approval"><li>Perforar paredes</li><li>Instalar nuevas luminarias</li></ul></div><div><strong>✕ No está permitido</strong><ul data-summary="blocked"><li>Derribar muros</li><li>Modificar instalaciones permanentes</li></ul></div></div><label class="check-row summary-consent"><input type="checkbox"> <span>Confirmo que estas condiciones son correctas y autorizo su publicación.</span></label></div><div class="photo-record"><div><span class="material-symbols-outlined">photo_camera</span><div><h3>Registro fotográfico previo</h3><p>Antes y después de cada reserva se podrán registrar paredes, pisos, techos, fachada, baños, mobiliario, equipos y daños existentes.</p></div></div><button class="secondary-btn" onclick="toast('Registro fotográfico añadido al flujo de reserva')">Configurar registro</button></div></div>`; }
function interventionSelect(label) { return `<select aria-label="${label}">${interventionOptions.map((option,i)=>`<option ${i===1?'selected':''}>${option}</option>`).join('')}</select>`; }
function updateInterventionSummary() { const rows=document.querySelectorAll('.intervention-row'); const groups={allowed:[],approval:[],blocked:[]}; rows.forEach(row=>{const value=row.querySelector('select')?.value||''; const label=row.querySelector('span')?.textContent; if (value.startsWith('Sí')||value==='Permitido') groups.allowed.push(label); if (value.startsWith('Solo')) groups.approval.push(label); if (value.startsWith('No')||value==='No permitido') groups.blocked.push(label);}); Object.entries(groups).forEach(([key,items])=>{const list=document.querySelector(`[data-summary="${key}"]`); if(list) list.innerHTML=(items.length?items.slice(0,4):['Sin condiciones seleccionadas']).map(item=>`<li>${item}</li>`).join('');}); }
function pricingPanel() { return `<div class="panel publish-panel pricing-panel"><div class="pricing-header"><div><h2>Valor y unidad mínima de arrendamiento</h2><p class="panel-help">Tú decides cuánto cobrar y si tu unidad mínima es por hora, día, semana o mes.</p></div><span class="material-symbols-outlined">calculate</span></div><div class="form-grid"><div class="form-field"><label>UNIDAD MÍNIMA</label><select id="price-unit"><option value="hour">Hora</option><option value="day">Día</option><option value="week">Semana</option><option value="month">Mes</option></select></div><div class="form-field"><label>VALOR FINAL QUE QUIERES COBRAR</label><input id="owner-price" type="number" min="0" placeholder="Ej. 60000" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>ADMINISTRACIÓN MENSUAL</label><input class="cost-input" data-cost="admin" type="number" min="0" value="0" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>SERVICIOS MENSUALES</label><input class="cost-input" data-cost="utilities" type="number" min="0" value="0" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>INTERNET / SEGURIDAD / OTROS</label><input class="cost-input" data-cost="other" type="number" min="0" value="0" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>MANTENIMIENTO MENSUAL</label><input class="cost-input" data-cost="maintenance" type="number" min="0" value="0" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>HORAS DISPONIBLES AL MES</label><input id="available-hours" type="number" min="1" value="160" oninput="calculateSuggestedPrice()"/></div><div class="form-field"><label>MARGEN DESEADO (%)</label><input id="target-margin" type="number" min="0" value="25" oninput="calculateSuggestedPrice()"/></div></div><div class="pricing-result"><div><span class="eyebrow">Sugerencia de Localmente</span><strong id="suggested-price">$0 / hora</strong><small id="pricing-breakdown">Calculada con tus costos y disponibilidad.</small></div><div class="pricing-owner-value"><span>Tu precio publicado</span><strong id="owner-price-display">Sin definir</strong></div></div><p class="pricing-note"><span class="material-symbols-outlined">info</span>La sugerencia es orientativa. El propietario decide el precio final y puede cambiarlo antes de publicar.</p></div>`; }
function calculateSuggestedPrice() { const panel=document.querySelector('.pricing-panel'); if (!panel) return; const costs=[...panel.querySelectorAll('.cost-input')].reduce((sum,input)=>sum+(Number(input.value)||0),0); const hours=Number(panel.querySelector('#available-hours')?.value)||1; const margin=(Number(panel.querySelector('#target-margin')?.value)||0)/100; const unit=panel.querySelector('#price-unit')?.value||'hour'; const divisors={hour:hours,day:Math.max(1,Math.round(hours/8)),week:Math.max(1,Math.round(hours/40)),month:1}; const labels={hour:'hora',day:'día',week:'semana',month:'mes'}; const suggested=Math.ceil(((costs*(1+margin))/divisors[unit])/1000)*1000; const format=value=>`$${new Intl.NumberFormat('es-CO').format(value)}`; const suggestedEl=panel.querySelector('#suggested-price'); const breakdown=panel.querySelector('#pricing-breakdown'); const ownerValue=panel.querySelector('#owner-price'); const ownerDisplay=panel.querySelector('#owner-price-display'); if(suggestedEl) suggestedEl.textContent=`${format(suggested)} / ${labels[unit]}`; if(breakdown) breakdown.textContent=`Costos mensuales ${format(costs)} · ${divisors[unit]} unidades estimadas al mes`; if(ownerDisplay) ownerDisplay.textContent=ownerValue?.value?`${format(Number(ownerValue.value))} / ${labels[unit]}`:'Sin definir'; }
function preparePublishForm() { const panel=document.querySelectorAll('.publish-layout > .publish-panel')[1]; if(!panel||panel.dataset.ready) return; panel.dataset.ready='true'; const fields=panel.querySelectorAll('.form-field input,.form-field select,.form-field textarea'); ['publish-name','publish-type','publish-area','publish-area-unit','publish-address','publish-specs'].forEach((id,index)=>fields[index]?.setAttribute('id',id)); const typeField=document.querySelector('#publish-type')?.closest('.form-field'); if(typeField&&!document.querySelector('#publish-furnishing')) typeField.insertAdjacentHTML('afterend','<div class="form-field"><label>ESTADO DEL ESPACIO</label><select id="publish-furnishing"><option>Amoblado</option><option>Semi amoblado</option><option>Sin amoblar</option></select></div>'); const address=document.querySelector('#publish-address'); if(address&&!document.querySelector('#publish-coordinates')) address.insertAdjacentHTML('afterend','<small id="publish-coordinates" class="coordinates-hint">La ubicación se convertirá en coordenadas al publicar.</small>'); const save=document.querySelector('.publish-actions .primary-btn'); if(save) save.onclick=publishSpaceFromForm; }
async function geocodeAddress(address) { try { const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=co&q=${encodeURIComponent(address+', Colombia')}`,{headers:{Accept:'application/json'}}); const results=await response.json(); if(results[0]) return {latitude:Number(results[0].lat),longitude:Number(results[0].lon)}; } catch(error) {} const city=normalizeCity(address); const center=cityCenters[city]; return {latitude:center[0],longitude:center[1]}; }
async function publishSpaceFromForm() { preparePublishForm(); const name=document.querySelector('#publish-name')?.value.trim()||'Nuevo espacio Localmente'; const address=document.querySelector('#publish-address')?.value.trim()||'Bogotá, Colombia'; const coordinates=await geocodeAddress(address); const priceUnit=document.querySelector('#price-unit')?.value||'day'; const ownerPrice=Number(document.querySelector('#owner-price')?.value)||0; const price=ownerPrice||100000; const space={id:`LOC-${Date.now()}`,title:name,name,location:address,latitude:coordinates.latitude,longitude:coordinates.longitude,mainImage:photos.emptyGallery,image:photos.emptyGallery,price,unit:`/${{hour:'hora',day:'día',week:'semana',month:'mes'}[priceUnit]}`,prices:{[priceUnit]:price},tags:['Nuevo espacio','Publicado'],furnishing:document.querySelector('#publish-furnishing')?.value||'Sin amoblar',availability:'Disponible',rating:null,distance:'Cerca de ti',businessTypes:['Otros'],description:document.querySelector('#publish-specs')?.value||'Espacio publicado por un propietario en Localmente.'}; spaces.push(space); searchState.location=normalizeCity(address); selectedSpaceId=space.id; toast('Espacio publicado con coordenadas válidas'); active='map'; render(); }
function addSearchEnhancements() {
  if (active === 'discover') {
    const search = document.querySelector('.search-bar');
    if (search) {
      search.insertAdjacentHTML('beforebegin', `<div class="search-intent"><span class="search-intent-label">¿Qué tipo de espacio necesitas?</span><button class="intent-option selected" onclick="this.parentElement.querySelectorAll('.intent-option').forEach(x=>x.classList.remove('selected'));this.classList.add('selected')"><span class="material-symbols-outlined">chair</span>Amoblado</button><button class="intent-option" onclick="this.parentElement.querySelectorAll('.intent-option').forEach(x=>x.classList.remove('selected'));this.classList.add('selected')"><span class="material-symbols-outlined">crop_square</span>Sin amoblar</button>` +
        `<button class="intent-option" onclick="active='map';render()"><span class="material-symbols-outlined">map</span>Ver mapa</button></div>`);
      search.insertAdjacentHTML('afterend', `<p class="search-note"><span class="material-symbols-outlined">location_on</span><span class="location-status">${userLocationLabel()}</span><button class="location-action" onclick="requestUserLocation(true)">${locationState.status==='ready'?'Actualizar ubicación':'Usar mi ubicación'}</button></p>`);
      const fields = document.querySelectorAll('.search-bar .search-field');
      const kinds = ['location','type','budget','dates'];
      fields.forEach((field,index) => { field.setAttribute('role','button'); field.tabIndex=0; field.onclick=()=>openSearchPicker(kinds[index]); field.onkeydown=e=>{if(e.key==='Enter'||e.key===' ') openSearchPicker(kinds[index]);} });
      fields[0].querySelector('strong').textContent=searchState.location;
      fields[1].querySelector('strong').textContent=searchState.type;
      fields[2].querySelector('strong').textContent=searchState.dates;
      const intentButtons=document.querySelectorAll('.search-intent .intent-option');
      intentButtons[0].onclick=()=>setFurnishing('furnished');
      intentButtons[1].onclick=()=>setFurnishing('unfurnished');
      intentButtons[0].classList.toggle('selected',searchState.furnishing==='furnished');
      intentButtons[1].classList.toggle('selected',searchState.furnishing==='unfurnished');
      const resultCards=document.querySelectorAll('.view > .cards .card');
      resultCards.forEach((result,index)=>{ const item=recommendedSpaces()[index]; const value=item?.furnishing || 'furnished'; const amount=Number(String(item?.price||0).replace(/\D/g,'')); const budgetOk=budgetMatches(amount,searchState.budget); result.style.display=(searchState.furnishing==='all'||value===searchState.furnishing)&&budgetOk?'':'none'; });
    }
  }
  if (active === 'filters') {
    const grid = document.querySelector('.filter-grid');
    if (grid) { grid.insertAdjacentHTML('afterbegin', `<div class="panel furnishing-panel"><h3>Amoblado</h3><p class="panel-help">Elige cómo quieres recibir el espacio.</p><div class="choice-grid compact"><button class="choice ${searchState.furnishing==='furnished'?'selected':''}" data-furnishing="furnished"><span class="material-symbols-outlined">chair</span>Amoblado</button><button class="choice ${searchState.furnishing==='unfurnished'?'selected':''}" data-furnishing="unfurnished"><span class="material-symbols-outlined">crop_square</span>Sin amoblar</button></div></div>`); const choices=grid.querySelectorAll('[data-furnishing]'); choices.forEach(choice=>choice.onclick=()=>setFurnishing(choice.dataset.furnishing)); }
  }
  if (active === 'publish') {
    const questionnaire = document.querySelector('.publish-questionnaire');
    if (questionnaire) questionnaire.insertAdjacentHTML('beforebegin', `<div class="panel publish-panel owner-details"><h2>Datos del propietario</h2><p class="panel-help">Estos datos crean tu perfil para administrar reservas y mensajes.</p><div class="form-grid"><div class="form-field"><label>NOMBRE COMPLETO</label><input placeholder="Ej. Laura Gómez"/></div><div class="form-field"><label>CORREO ELECTRÓNICO</label><input type="email" placeholder="laura@email.com"/></div><div class="form-field"><label>TELÉFONO</label><input type="tel" placeholder="+57 300 000 0000"/></div><div class="form-field"><label>TIPO DE CUENTA</label><select><option>Propietario</option><option>Administrador autorizado</option></select></div></div><label class="check-row owner-consent"><input type="checkbox"> <span>Acepto recibir solicitudes y mensajes sobre este espacio.</span></label></div><div class="panel publish-panel modifications-panel"><h2>Intervenciones y modificaciones permitidas</h2><p class="panel-help">Define qué puede adaptar el emprendedor y cuándo necesita tu aprobación.</p><div class="modification-grid">${['Pintura y decoración temporal','Instalar mobiliario o exhibidores','Letrero, vinilo o aviso exterior','Perforaciones y fijaciones','Conexiones eléctricas o de agua','Adecuaciones temporales del espacio'].map((item,i)=>`<div class="modification-row"><span>${item}</span><select aria-label="${item}"><option>Permitida</option><option selected>Solo con autorización previa</option><option>No permitida</option></select></div>`).join('')}</div><div class="form-field"><label>CONDICIONES ADICIONALES</label><textarea rows="3" placeholder="Describe horarios, materiales permitidos, reparaciones, permisos o condiciones de entrega..."></textarea></div></div>`);
    if (questionnaire && !document.querySelector('.pricing-panel')) questionnaire.insertAdjacentHTML('beforebegin', pricingPanel());
    document.querySelector('#price-unit')?.addEventListener('change', calculateSuggestedPrice);
    calculateSuggestedPrice();
    preparePublishForm();
    const oldModifications = document.querySelector('.modifications-panel');
    if (questionnaire && oldModifications) {
      oldModifications.remove();
      questionnaire.insertAdjacentHTML('beforebegin', interventionPanel());
      document.querySelectorAll('.modifications-panel select').forEach(select=>select.addEventListener('change', updateInterventionSummary));
    }
  }
  if (active==='spaceDetail') { const button=document.querySelector('.space-detail-card .primary-btn'); if(button) button.onclick=()=>{active='reserve';render();}; }
}
function setFurnishing(value) { searchState.furnishing=value; if (active==='discover') render(); else { document.querySelectorAll('[data-furnishing]').forEach(choice=>choice.classList.toggle('selected',choice.dataset.furnishing===value)); toast(value==='furnished'?'Mostrando espacios amoblados':'Mostrando espacios sin amoblar'); } }
function budgetMatches(amount,budget) { if(!budget||budget==='Cualquier presupuesto') return true; if(budget.includes('Hasta')) return amount<=100000; if(budget.includes('$100.000 -')) return amount>100000&&amount<=300000; if(budget.includes('$300.000 -')) return amount>300000&&amount<=700000; if(budget.includes('Más de')) return amount>700000; return true; }
function openSearchPicker(kind) {
  const options = {
    location:cityLabels,
    type:['Cualquier categoría','Gastro','Retail','Oficinas','Salud','Belleza','Talleres'],
    budget:['Cualquier presupuesto','Hasta $100.000','$100.000 - $300.000','$300.000 - $700.000','Más de $700.000'],
    dates:['Agregar fechas','Hoy','Esta semana','Este fin de semana']
  }[kind];
  const labels={location:'¿Dónde quieres buscar?',type:'¿Qué tipo de espacio buscas?',dates:'¿Cuándo necesitas el espacio?'};
  document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal search-picker"><button class="icon-btn modal-close" onclick="this.closest('.modal-backdrop').remove()"><span class="material-symbols-outlined">close</span></button><p class="eyebrow">Buscar espacios</p><h2>${labels[kind]}</h2><div class="picker-options">${options.map(option=>`<button class="picker-option" onclick="applySearchChoice('${kind}', '${option.replace(/'/g,"\\'")}')"><span>${option}</span><span class="material-symbols-outlined">chevron_right</span></button>`).join('')}</div></div></div>`;
}
function applySearchChoice(kind, value) {
  searchState[kind]=value;
  document.querySelector('.modal-backdrop')?.remove();
  const fieldIndex={location:0,type:1,budget:2,dates:3}[kind];
  const field=document.querySelectorAll('.search-bar .search-field')[fieldIndex];
  if (field) field.querySelector('strong').textContent=value;
  if (kind==='budget') { render(); return; }
  toast(`${value} seleccionado`);
}
const cityCenters = {
  'Bogotá, Colombia':[4.711,-74.072], 'Medellín, Colombia':[6.244,-75.581], 'Cali, Colombia':[3.452,-76.532], 'Barranquilla, Colombia':[10.968,-74.781], 'Cartagena, Colombia':[10.391,-75.479], 'Bucaramanga, Colombia':[7.119,-73.122], 'Pereira, Colombia':[4.814,-75.694], 'Manizales, Colombia':[5.068,-75.517], 'Santa Marta, Colombia':[11.241,-74.211], 'Ibagué, Colombia':[4.438,-75.232]
};
const cityLabels = Object.keys(cityCenters);
const mapSpaceTemplates = [
  { name:'Local Gastro de barrio', detail:'Gastro · Amoblado', price:45000, unit:'hora' },
  { name:'Salón comercial abierto', detail:'Retail · Sin amoblar', price:180000, unit:'día' },
  { name:'Garaje con potencial', detail:'Potencial · Garaje', price:250000, unit:'semana' },
  { name:'Jardín frontal tipo galería', detail:'Potencial · Exterior', price:320000, unit:'quincena' },
  { name:'Oficina flexible', detail:'Oficina · Amoblado', price:900000, unit:'mes' }
];
function normalizeCity(value) { const text=String(value||'').toLowerCase(); const found=Object.keys(cityCenters).find(city=>text.includes(city.split(',')[0].toLowerCase())); return found||'Bogotá, Colombia'; }
function ensureCitySpaces(city) { const existing=spaces.filter(space=>normalizeCity(space.location||'')===city && Number.isFinite(space.latitude) && Number.isFinite(space.longitude)); if(existing.length>=5) return existing; const center=cityCenters[city]||cityCenters['Bogotá, Colombia']; const cityName=city.split(',')[0]; let seed=[...city].reduce((sum,char)=>((sum*31)+char.charCodeAt(0))%997,17); const random=()=>{seed=(seed*9301+49297)%233280; return seed/233280;}; mapSpaceTemplates.slice(existing.length).forEach((template,index)=>{ const id=`LOC-${cityName.slice(0,3).toUpperCase()}-${Date.now().toString(36)}-${index}`; const space={id,title:`${template.name} ${cityName}`,name:`${template.name} ${cityName}`,location:`${cityName}, Colombia`,latitude:center[0]+((random()-.5)*.065),longitude:center[1]+((random()-.5)*.085),mainImage:photos.emptyGallery, image:photos.emptyGallery,price:template.price,unit:`/${template.unit}`,prices:{hour:template.unit==='hora'?template.price:undefined,day:template.unit==='día'?template.price:undefined,week:template.unit==='semana'?template.price:undefined,fortnight:template.unit==='quincena'?template.price:undefined,month:template.unit==='mes'?template.price:undefined},tags:template.detail.split(' · '),detail:template.detail, furnishing:template.detail.includes('Sin')?'Sin amoblar':template.detail.includes('Amoblado')?'Amoblado':'Sin amoblar',availability:'Disponible',rating:4.8,distance:'2.4 km',businessTypes:template.detail.includes('Gastro')?['Restaurante','Cafetería']:template.detail.includes('Retail')?['Boutique','Showroom']:['Oficina','Consultorio'],badge:'Publicado'}; spaces.push(space); }); return spaces.filter(space=>normalizeCity(space.location||'')===city && Number.isFinite(space.latitude) && Number.isFinite(space.longitude)); }
function citySpaces(city) { return ensureCitySpaces(city).map(space=>({ ...space, position:[space.latitude,space.longitude], name:space.name||space.title, detail:space.detail||space.tags?.join(' · '), price:space.price||Object.values(space.prices||{}).find(Boolean)||0, unit:(space.unit||'/día').replace('/',''), selected:space.id===selectedSpaceId })); }
function formatMapPrice(value) { return `$${new Intl.NumberFormat('es-CO').format(value)}`; }
let activeMap=null; let activeMapLayer=null; let mapRefreshTimer=null;
function filteredMapSpaces(city,map) { const bounds=map.getBounds(); return ensureCitySpaces(city).filter(space=>Number.isFinite(space.latitude)&&Number.isFinite(space.longitude)&&bounds.contains([space.latitude,space.longitude])).filter(space=>mapState.business==='all'||(space.businessTypes||[]).includes(mapState.business)).filter(space=>mapState.furnishing==='all'||space.furnishing===mapState.furnishing).filter(space=>mapState.availability==='all'||space.availability===mapState.availability).filter(space=>{const amount=Number(space.price)||0; return mapState.price==='all'||(mapState.price==='low'&&amount<=100000)||(mapState.price==='mid'&&amount>100000&&amount<=300000)||(mapState.price==='high'&&amount>300000&&amount<=700000)||(mapState.price==='premium'&&amount>700000);}); }
function spaceMarkerIcon(space,cluster=false,count=1) { if(cluster) return L.divIcon({className:'localmente-cluster-icon',html:`<div class="localmente-cluster"><img src="${logo}" alt="Localmente"><strong>${count}</strong></div>`,iconSize:[58,58],iconAnchor:[29,29]}); return L.divIcon({className:'localmente-map-icon',html:`<div class="real-space-marker ${space.id===selectedSpaceId?'selected':''}"><img src="${logo}" alt="Localmente"><span class="marker-price">${formatMapPrice(space.price||0)}${space.unit||''}</span></div>`,iconSize:[116,128],iconAnchor:[58,116],popupAnchor:[0,-116]}); }
function selectMapSpace(space,map) { selectedSpaceId=space.id; map.setView([space.latitude,space.longitude],Math.max(map.getZoom(),15),{animate:true}); renderSelectedMapCard(space); renderMapMarkers(map,normalizeCity(space.location||'')); }
function selectMapSpaceById(id) { const space=spaces.find(item=>item.id===id); if(space&&activeMap) selectMapSpace(space,activeMap); }
function renderSelectedMapCard(space) { const card=document.querySelector('.map-selected-card'); if(!card) return; const prices=space.prices||{}; card.innerHTML=`<img src="${space.mainImage||space.image||logo}" alt="${space.name||space.title}"><div class="map-selected-content"><button class="map-card-close" onclick="selectedSpaceId=null;document.querySelector('.map-selected-card').classList.remove('show')">×</button><h3>${space.name||space.title}</h3><p>${space.businessTypes?.[0]||space.tags?.[0]||'Espacio'} · ${space.furnishing||'Sin amoblar'} · ⭐ ${space.rating||'—'}</p><small>📍 ${space.distance||'Cerca de ti'}</small><strong>${formatMapPrice(space.price||Object.values(prices).find(Boolean)||0)}${space.unit||'/día'}</strong><div class="map-secondary-prices">${Object.entries(prices).filter(([,value])=>value&&`${formatMapPrice(value)}${space.unit||''}`!==`${formatMapPrice(space.price||0)}${space.unit||''}`).map(([key,value])=>`<span>${formatMapPrice(value)}/${{hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[key]}</span>`).join('')}</div><div class="map-selected-actions"><button class="icon-btn" onclick="toggleHeart(this)"><span class="material-symbols-outlined">favorite</span></button><button class="primary-btn" onclick="openSpaceDetails('${space.id}')">Ver detalles</button></div></div>`; card.classList.add('show'); }
function renderMapMarkers(map,city) { if(activeMapLayer) activeMapLayer.remove(); activeMapLayer=L.layerGroup().addTo(map); const items=filteredMapSpaces(city,map); const zoom=map.getZoom(); const cell=Math.max(.003,.12/Math.pow(2,Math.max(0,zoom-10))); const groups=new Map(); items.forEach(space=>{const key=`${Math.floor(space.latitude/cell)}:${Math.floor(space.longitude/cell)}`; if(!groups.has(key)) groups.set(key,[]); groups.get(key).push(space);}); groups.forEach(group=>{if(group.length>1){const lat=group.reduce((sum,s)=>sum+s.latitude,0)/group.length; const lon=group.reduce((sum,s)=>sum+s.longitude,0)/group.length; const marker=L.marker([lat,lon],{icon:spaceMarkerIcon(group[0],true,group.length),zIndexOffset:700}); marker.on('click',()=>map.setView([lat,lon],map.getZoom()+2,{animate:true})); marker.addTo(activeMapLayer);} else {const space=group[0]; const marker=L.marker([space.latitude,space.longitude],{icon:spaceMarkerIcon(space),zIndexOffset:space.id===selectedSpaceId?900:100}); marker.on('click',()=>selectMapSpace(space,map)); marker.addTo(activeMapLayer);}}); const count=document.querySelector('.map-results-count'); if(count) count.textContent=`${items.length} espacios visibles`; const mapList=document.querySelector('.map-list'); if(mapList) mapList.innerHTML=items.slice(0,12).map(space=>`<div class="map-card ${space.id===selectedSpaceId?'selected':''}" onclick="selectMapSpaceById('${space.id}')"><div class="map-card-logo"><img src="${logo}" alt="Localmente"></div><div class="card-content"><h3>${space.name||space.title}</h3><div class="card-location">${space.businessTypes?.[0]||space.tags?.[0]||'Espacio'} · ${space.furnishing||'Sin amoblar'} · ⭐ ${space.rating||'—'}</div><div class="price">${formatMapPrice(space.price||Object.values(space.prices||{}).find(Boolean)||0)}<small>${space.unit||'/día'}</small></div></div></div>`).join(''); }
function scheduleMapRefresh() { clearTimeout(mapRefreshTimer); mapRefreshTimer=setTimeout(()=>{if(activeMap) renderMapMarkers(activeMap,normalizeCity(searchState.location));},260); }
function addMapEnhancements() { const panel=document.querySelector('.map-panel'); if(!panel||panel.querySelector('.map-filter-bar')) return; panel.querySelector('.map-top')?.insertAdjacentHTML('afterend',`<div class="map-filter-bar"><select data-map-filter="price"><option value="all">Precio</option><option value="low">Hasta $100.000</option><option value="high">Más de $100.000</option></select><select data-map-filter="business"><option value="all">Tipo de negocio</option>${['Restaurante','Cafetería','Barbería','Salón de belleza','Boutique','Oficina','Consultorio','Showroom','Food truck','Papelería','Tecnología','Otros'].map(item=>`<option>${item}</option>`).join('')}</select><select data-map-filter="furnishing"><option value="all">Tipo de espacio</option><option>Amoblado</option><option>Semi amoblado</option><option>Sin amoblar</option></select><select data-map-filter="availability"><option value="all">Disponibilidad</option><option value="Disponible hoy">Disponible hoy</option><option value="Disponible">Disponible</option></select><button class="map-near-btn" onclick="locateMapUser()"><span class="material-symbols-outlined">my_location</span>Cerca de mí</button><button class="map-more-btn" onclick="active='filters';render()">Más filtros</button></div><div class="map-results-count">0 espacios visibles</div>`); panel.querySelector('.map-list')?.insertAdjacentHTML('beforebegin','<div class="map-selected-card"></div>'); panel.querySelectorAll('[data-map-filter]').forEach(select=>{select.value=mapState[select.dataset.mapFilter]; select.onchange=()=>{mapState[select.dataset.mapFilter]=select.value; if(activeMap) renderMapMarkers(activeMap,normalizeCity(searchState.location));};}); }
function locateMapUser() { if(!navigator.geolocation){toast('No pudimos acceder a tu ubicación');return;} requestUserLocation(true); if(activeMap&&locationState.latitude&&locationState.longitude) activeMap.setView([locationState.latitude,locationState.longitude],15,{animate:true}); }
function configureMapBudgetFilter() { const filter=document.querySelector('[data-map-filter="price"]'); if(!filter) return; filter.innerHTML='<option value="all">Presupuesto</option><option value="low">Hasta $100.000</option><option value="mid">$100.000 - $300.000</option><option value="high">$300.000 - $700.000</option><option value="premium">Más de $700.000</option>'; filter.value=mapState.price; }
function openSpaceDetails(id) { const space=spaces.find(item=>item.id===id); if(!space) return; selectedSpaceId=id; active='spaceDetail'; render(); }
function spaceDetail() { const space=spaces.find(item=>item.id===selectedSpaceId)||spaces[0]; const prices=space.prices||{}; return `<section class="view flow-screen space-detail-view"><button class="back-btn" onclick="active='map';render()"><span class="material-symbols-outlined">arrow_back</span> Volver al mapa</button><div class="space-detail-layout"><div class="space-detail-cover" style="background-image:url('${space.mainImage||space.image||logo}')"><span class="badge">${space.availability||'Disponible'}</span></div><div class="panel space-detail-card"><p class="eyebrow">${space.id}</p><h1>${space.name||space.title}</h1><p class="card-location"><span class="material-symbols-outlined">location_on</span>${space.location||'Colombia'} · ${space.distance||'Cerca de ti'}</p><div class="detail-tags"><span>${space.businessTypes?.[0]||'Espacio comercial'}</span><span>${space.furnishing||'Sin amoblar'}</span><span>⭐ ${space.rating||'—'}</span></div><p class="space-detail-copy">${space.description||'Espacio temporal registrado en Localmente para actividades comerciales, creativas y de servicios.'}</p><div class="detail-price-list">${Object.entries(prices).filter(([,value])=>value).map(([key,value])=>`<div><span>Por ${{hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[key]}</span><strong>${formatMapPrice(value)}</strong></div>`).join('')}</div><button class="primary-btn full" onclick="toast('Solicitud de reserva iniciada')">Solicitar reserva</button></div></div></section>`; }
function initRealMap() {
  configureMapBudgetFilter();
  const panel = document.querySelector('.map-panel');
  if (!panel || typeof L === 'undefined') return;
  panel.querySelectorAll('.pin').forEach(pin => pin.style.display='none');
  panel.querySelectorAll('.real-map-canvas').forEach(node => node.remove());
  panel.insertAdjacentHTML('afterbegin', '<div id="real-map-canvas" class="real-map-canvas"></div>');
  const city=normalizeCity(searchState.location); const center=cityCenters[city];
  const map = L.map('real-map-canvas', { zoomControl:true }).setView(center, 12);
  map.getPane('markerPane').style.zIndex=700;
  map.getPane('popupPane').style.zIndex=800;
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom:19, attribution:'© OpenStreetMap contributors' }).addTo(map);
  activeMap=map; renderMapMarkers(map,city);
  map.on('moveend zoomend',scheduleMapRefresh);
  const mapList=panel.querySelector('.map-list'); if (mapList) mapList.innerHTML='';
  let userMarker;
  const locate = () => { if (!navigator.geolocation) return; navigator.geolocation.getCurrentPosition(pos => { const point=[pos.coords.latitude,pos.coords.longitude]; if (!userMarker) userMarker=L.marker(point,{icon:L.divIcon({className:'',html:'<div class="real-user-marker"></div>',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(map).bindTooltip('Tu ubicación',{direction:'top'}); else userMarker.setLatLng(point); },()=>{}, {enableHighAccuracy:true,timeout:8000,maximumAge:300000}); };
  const search = panel.querySelector('.map-top input');
  if (search) search.value=city;
  setTimeout(()=>map.invalidateSize(),200);
  locate();
}
function reservationSpace() { return spaces.find(item=>item.id===selectedSpaceId)||spaces[0]; }
function reservationPrice() { const space=reservationSpace(); const unit=reservationState.unit; return Number(space.prices?.[unit])||Number(space.price)||0; }
function reservationTotal() { const base=reservationPrice()*Math.max(1,Number(reservationState.quantity)||1); return {base,service:Math.round(base*.08),deposit:Math.round(base*.2),total:Math.round(base*1.28)}; }
function updateReservationEstimate() { const total=reservationTotal(); const unitLabel={hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[reservationState.unit]; document.querySelector('#reservation-unit-price')?.replaceChildren(document.createTextNode(`${formatMapPrice(reservationPrice())} / ${unitLabel}`)); document.querySelector('#reservation-base')?.replaceChildren(document.createTextNode(formatMapPrice(total.base))); document.querySelector('#reservation-service')?.replaceChildren(document.createTextNode(formatMapPrice(total.service))); document.querySelector('#reservation-deposit')?.replaceChildren(document.createTextNode(formatMapPrice(total.deposit))); document.querySelector('#reservation-total')?.replaceChildren(document.createTextNode(formatMapPrice(total.total))); }
function reserve() { const space=reservationSpace(); const availableUnits=Object.keys(space.prices||{}).filter(key=>space.prices[key]); const defaultUnit=availableUnits[0]||'day'; reservationState.unit=availableUnits.includes(reservationState.unit)?reservationState.unit:defaultUnit; return `<section class="view flow-screen reservation-view"><button class="back-btn" onclick="active='spaceDetail';render()"><span class="material-symbols-outlined">arrow_back</span> Volver al espacio</button><div class="section-head reservation-heading"><div><p class="eyebrow">Reserva segura</p><h1>Configura tu reserva</h1><p>Elige la unidad mínima publicada por el propietario.</p></div><span class="reservation-step">1 de 3</span></div><div class="reservation-layout"><div class="panel reservation-form"><div class="reservation-space-head"><img src="${space.mainImage||space.image||logo}" alt="${space.name||space.title}"><div><h2>${space.name||space.title}</h2><p>${space.location||'Colombia'} · ${space.furnishing||'Sin amoblar'}</p></div></div><div class="form-grid"><div class="form-field"><label>UNIDAD DE RESERVA</label><select id="reservation-unit" onchange="reservationState.unit=this.value;updateReservationEstimate()">${availableUnits.map(unit=>`<option value="${unit}" ${reservationState.unit===unit?'selected':''}>Por ${{hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[unit]}</option>`).join('')}</select></div><div class="form-field"><label>CANTIDAD DE UNIDADES</label><input id="reservation-quantity" type="number" min="1" value="${reservationState.quantity}" oninput="reservationState.quantity=this.value;updateReservationEstimate()"></div><div class="form-field"><label>FECHA DE INICIO</label><input type="date" value="${reservationState.start}" onchange="reservationState.start=this.value"></div><div class="form-field"><label>FECHA DE FINALIZACIÓN</label><input type="date" value="${reservationState.end}" onchange="reservationState.end=this.value"></div></div><div class="reservation-note"><span class="material-symbols-outlined">verified_user</span><span>El propietario revisará la solicitud y las condiciones del espacio antes de confirmarla.</span></div><button class="primary-btn full" onclick="active='reserveAccount';render()">Continuar con la reserva <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div><div class="panel reservation-summary"><h2>Desglose</h2><div class="detail-row"><span>Tarifa publicada</span><b id="reservation-unit-price"></b></div><div class="detail-row"><span>Uso del espacio</span><span id="reservation-base"></span></div><div class="detail-row"><span>Servicio Localmente · 8%</span><span id="reservation-service"></span></div><div class="detail-row"><span>Depósito de garantía</span><span id="reservation-deposit"></span></div><div class="total-row"><span>Total estimado</span><strong id="reservation-total"></strong></div><small>El depósito se libera después del registro fotográfico de salida y la revisión del propietario.</small></div></div></section>`; }
function reserveAccount() { const space=reservationSpace(); return `<section class="view flow-screen narrow checkout-view"><button class="back-btn" onclick="active='reserve';render()"><span class="material-symbols-outlined">arrow_back</span> Volver a la reserva</button><div class="checkout-progress"><span class="done">1</span><span class="active">2</span><span>3</span></div><div class="panel checkout-card"><p class="eyebrow">Crea tu cuenta de emprendedor</p><h1>Regístrate para solicitar este espacio</h1><p class="checkout-copy">Necesitamos tus datos para que el propietario pueda revisar la solicitud y enviarte los detalles.</p><div class="form-grid"><div class="form-field"><label>NOMBRE COMPLETO</label><input id="guest-name" placeholder="Ej. Camila Rodríguez"></div><div class="form-field"><label>CORREO ELECTRÓNICO</label><input id="guest-email" type="email" placeholder="camila@email.com"></div><div class="form-field"><label>TELÉFONO</label><input placeholder="+57 300 000 0000"></div><div class="form-field"><label>CONTRASEÑA</label><input type="password" placeholder="Mínimo 8 caracteres"></div></div><label class="check-row"><input type="checkbox"> <span>Acepto los términos de reserva y las condiciones del espacio.</span></label><button class="primary-btn full" onclick="reservationState.guestName=document.querySelector('#guest-name').value||'Emprendedor Localmente';reservationState.guestEmail=document.querySelector('#guest-email').value||'correo@ejemplo.com';active='payment';render()">Continuar al pago <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button><small class="secure-note"><span class="material-symbols-outlined">lock</span> Tus datos se usarán únicamente para gestionar esta reserva.</small></div><p class="checkout-space-reference">Reservando: <b>${space.name||space.title}</b></p></section>`; }
function payment() { const space=reservationSpace(); const total=reservationTotal(); return `<section class="view flow-screen checkout-view"><button class="back-btn" onclick="active='reserveAccount';render()"><span class="material-symbols-outlined">arrow_back</span> Volver a tus datos</button><div class="checkout-progress"><span class="done">1</span><span class="done">2</span><span class="active">3</span></div><div class="payment-layout"><div class="panel payment-card"><p class="eyebrow">Pago seguro</p><h1>Confirma y paga tu reserva</h1><div class="payment-methods"><button class="payment-method ${reservationState.paymentMethod==='card'?'selected':''}" onclick="reservationState.paymentMethod='card';render()"><span class="material-symbols-outlined">credit_card</span> Tarjeta</button><button class="payment-method ${reservationState.paymentMethod==='pse'?'selected':''}" onclick="reservationState.paymentMethod='pse';render()"><span class="material-symbols-outlined">account_balance</span> PSE</button><button class="payment-method ${reservationState.paymentMethod==='nequi'?'selected':''}" onclick="reservationState.paymentMethod='nequi';render()"><span class="material-symbols-outlined">phone_iphone</span> Nequi</button></div>${reservationState.paymentMethod==='card'?`<div class="form-field"><label>NÚMERO DE TARJETA</label><input placeholder="0000 0000 0000 0000"></div><div class="form-grid"><div class="form-field"><label>NOMBRE EN LA TARJETA</label><input placeholder="Camila Rodríguez"></div><div class="form-field"><label>CÓDIGO DE SEGURIDAD</label><input placeholder="CVV"></div><div class="form-field"><label>VENCIMIENTO</label><input placeholder="MM / AA"></div></div>`:`<div class="payment-provider"><span class="material-symbols-outlined">${reservationState.paymentMethod==='pse'?'account_balance':'phone_iphone'}</span><h3>${reservationState.paymentMethod==='pse'?'Paga con PSE':'Paga con Nequi'}</h3><p>Te redirigiremos a la plataforma para autorizar el pago de forma segura.</p></div>`}<label class="check-row"><input type="checkbox"> <span>Acepto las condiciones de la reserva y autorizo el cobro de ${formatMapPrice(total.total)}.</span></label><button class="primary-btn full" onclick="active='reservationDone';render()">Pagar y solicitar reserva <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">lock</span></button></div><div class="panel payment-summary"><img src="${space.mainImage||space.image||logo}" alt=""><h2>${space.name||space.title}</h2><p>${space.location||'Colombia'} · ${reservationState.quantity} unidad(es)</p><div class="total-row"><span>Total</span><strong>${formatMapPrice(total.total)}</strong></div><small>Incluye tarifa del espacio, servicio Localmente y depósito de garantía.</small></div></div></section>`; }
function reservationDone() { const space=reservationSpace(); const total=reservationTotal(); return `<section class="view flow-screen confirmation reservation-confirmation"><div class="success-icon"><span class="material-symbols-outlined">check_circle</span></div><p class="eyebrow">Solicitud enviada</p><h1>¡Tu reserva está en camino!</h1><p>El propietario recibirá tu solicitud y te enviaremos una confirmación a <b>${reservationState.guestEmail||'tu correo'}</b>.</p><div class="panel"><div class="detail-row"><span>Espacio</span><b>${space.name||space.title}</b></div><div class="detail-row"><span>Unidad reservada</span><b>${reservationState.quantity} · Por ${{hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[reservationState.unit]}</b></div><div class="detail-row"><span>Total estimado</span><b>${formatMapPrice(total.total)}</b></div><div class="detail-row"><span>Código de solicitud</span><b>LOC-${String(Date.now()).slice(-6)}</b></div></div><button class="primary-btn full" onclick="active='discover';render()">Volver a explorar</button></section>`; }
function render() { const views={discover, map:mapView, potential, publish, spaceDetail, reserve, reserveAccount, payment, reservationDone, owner, inbox, verify:verifyStart, favorites, filters, booking, confirmation, profile, chatDetail, verifyStart, verifyDoc, verifySelfie, verifyBusiness, verifyStatus}; shell(views[active]()); addSearchEnhancements(); if (active==='reserve') updateReservationEstimate(); if (active==='map') { addMapEnhancements(); const mapSearch=document.querySelector('.map-top input'); mapSearch.value=searchState.location; mapSearch.onkeydown=event=>{if(event.key==='Enter'){searchState.location=mapSearch.value;render();}}; initRealMap(); } if (active==='profile') document.querySelector('.profile-hero p').textContent='128 reseñas · Bogotá'; }
const renderView = render;
const currentUser = { firstName:'Rodrigo', displayName:'Rodrigo M.' };
render = function() { renderView(); if (active==='discover') { const hero=document.querySelector('.hero'); const copy=hero?.firstElementChild; if(copy) { copy.classList.add('hero-copy'); copy.querySelector('.eyebrow')?.remove(); copy.querySelector('h1').textContent=`${currentUser.firstName}, ¿necesitas un local para tu negocio?`; copy.querySelector('p:not(.eyebrow)').textContent='Encuentra el local comercial ideal para que tu negocio comience a facturar.'; const cta=copy.querySelector('.primary-btn'); if(cta) cta.innerHTML='Explorar locales <span aria-hidden="true">→</span>'; } } };
render();
if (active==='discover') requestUserLocation();
